This Terraform configuration creates an AWS CodeBuild project with:

- An example IAM role for CodeBuild
- IAM permissions for CloudWatch Logs and S3 access
- A primary S3 source
- Multiple secondary S3 sources
- A primary S3 artifact output
- Multiple secondary S3 artifact outputs
- Example environment variables
- CloudWatch logging enabled
- Required S3 buckets for sources and artifacts

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  name_prefix = "example-codebuild-${random_id.suffix.hex}"
}

resource "aws_s3_bucket" "source_bucket" {
  bucket = "${local.name_prefix}-sources"
}

resource "aws_s3_bucket" "artifact_bucket" {
  bucket = "${local.name_prefix}-artifacts"
}

